-- Diagnostic (facultatif) --------------------------------------------------
-- Un `avec_tableau` inférieur au compte attendu ne vient PAS d'un UPDATE raté :
-- il vient de leçons qui n'existent pas dans cette base, faute d'avoir exécuté
-- leur seed de contenu. La requête ci-dessous nomme, sur TOUTE la base, les
-- cours encore en prose — c'est le seul inventaire qui compte.
-- SELECT id, title FROM public.lessons WHERE content NOT LIKE '%|%|%' ORDER BY title;
